class Store { late SharedPreferences p; List<Map<String,dynamic>> items=[], customers=[], rentals=[]; Future<void> load()async{p=await SharedPreferences.getInstance();items=read('rf_items');customers=read('rf_customers');rentals=read('rf_rentals');} List<Map<String,dynamic>> read(String k){final s=p.getString(k);if(s==null)return[];try{return(List.from(jsonDecode(s))).map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){return[];}} Future<void> save()async{await p.setString('rf_items',jsonEncode(items));await p.setString('rf_customers',jsonEncode(customers));await p.setString('rf_rentals',jsonEncode(rentals));}}
int ni(dynamic v)=>v is num?v.toInt():int.tryParse('$v')??0; double nd(dynamic v)=>v is num?v.toDouble():double.tryParse('$v')??0; String rs(dynamic v)=>nd(v).toStringAsFixed(nd(v)%1==0?0:2); String dateNow(){final d=DateTime.now();return '${d.day.toString().padLeft(2,'0')} ${_months[d.month-1]} ${d.year}';} const _months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

