 Future<void>back(){if(tab!=0){setState(()=>tab=0);return Future.value();}final n=DateTime.now();if(backAt!=null&&n.difference(backAt!)<const Duration(seconds:2))return SystemNavigator.pop();backAt=n;ScaffoldMessenger.of(context)..hideCurrentSnackBar()..showSnackBar(const SnackBar(content:Text('Press back again to exit'),duration:Duration(seconds:2)));return Future.value();}
 Future<void>checkUpdate({bool silent=false})async{if(!silent)showDialog(context:context,barrierDismissible:false,builder:(_)=>const AlertDialog(content:Row(children:[CircularProgressIndicator(color:primary),SizedBox(width:16),Text('Checking for updates...')])));Map<String,dynamic>? info;try{final c=HttpClient();final r=await c.getUrl(Uri.parse(updateUrl));final resp=await r.close();if(resp.statusCode==200)info=jsonDecode(await resp.transform(utf8.decoder).join()) as Map<String,dynamic>;c.close();}catch(_){ }if(!mounted)return;if(!silent)Navigator.pop(context);if(info==null){if(!silent)showMsg('Unable to check updates right now.');return;}final latest=ni(info['build']);if(latest<=currentBuild){if(!silent)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('You are up to date'),content:Text('RentFlow $currentVersion is the latest version.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('OK'))]));return;}showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Update available'),content:Text('RentFlow ${info['version']??''} is available.\n\n${info['releaseNotes']??''}'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Later')),FilledButton(onPressed:()async{await launchUrl(Uri.parse('${info['downloadUrl']??websiteUrl}'),mode:LaunchMode.externalApplication);if(context.mounted)Navigator.pop(context);},child:const Text('Update Now'))]));}
