 @override Widget build(BuildContext context){if(busy)return const Scaffold(body:Center(child:CircularProgressIndicator(color:primary)));final pages=[Home(store:store,onRefresh:refresh,onTab:(i)=>setState(()=>tab=i)),ItemsPage(store:store,onRefresh:refresh),CustomersPage(store:store,onRefresh:refresh),ReportsPage(store:store)];return PopScope(canPop:false,onPopInvokedWithResult:(did,_) {if(!did)back();},child:Scaffold(body:IndexedStack(index:tab,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),indicatorColor:mint,destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home_rounded),label:'Home'),NavigationDestination(icon:Icon(Icons.inventory_2_outlined),selectedIcon:Icon(Icons.inventory_2_rounded),label:'Items'),NavigationDestination(icon:Icon(Icons.people_outline),selectedIcon:Icon(Icons.people_rounded),label:'Customers'),NavigationDestination(icon:Icon(Icons.bar_chart_outlined),selectedIcon:Icon(Icons.bar_chart_rounded),label:'Reports')]));}
 void refresh()=>setState((){});
}

