Future<void>receiveForm(BuildContext c,Store s,VoidCallback refresh)async{final open=s.rentals.where((r)=>ni(r['qty'])>ni(r['received'])).toList();if(open.isEmpty){showDialog(context:c,builder:(_)=>const AlertDialog(title:Text('Receive Item'),content:Text('No issued items are pending return.')));return;}String selected='${open.first['customer']} • ${open.first['item']}';final amount=TextEditingController(text:'${ni(open.first['qty'])-ni(open.first['received'])}');await showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Receive Item'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:selected,items:open.map((r)=>DropdownMenuItem(value:'${r['customer']} • ${r['item']}',child:Text('${r['customer']} • ${r['item']}'))).toList(),onChanged:(v)=>selected=v??selected,decoration:const InputDecoration(labelText:'Rental')),const SizedBox(height:10),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Received quantity'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{final r=open.firstWhere((x)=>'${x['customer']} • ${x['item']}'==selected);final rec=ni(amount.text);r['received']=(ni(r['received'])+rec).clamp(0,ni(r['qty']));final it=s.items.firstWhere((x)=>x['name']==r['item']);it['available']=ni(it['available'])+rec;await s.save();refresh();if(c.mounted)Navigator.pop(c);},child:const Text('Receive'))]));}
Future<void>customerReport(BuildContext c,Store s,String name)async{final rows=s.rentals.where((r)=>r['customer']==name).toList();await showDialog(context:c,builder:(_)=>AlertDialog(title:Text(name),content:SizedBox(width:520,child:SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:const[DataColumn(label:Text('Date')),DataColumn(label:Text('Item')),DataColumn(label:Text('Issued')),DataColumn(label:Text('Received')),DataColumn(label:Text('Days')),DataColumn(label:Text('Amount')),DataColumn(label:Text('Due'))],rows:rows.map((r){final q=ni(r['qty']),rec=ni(r['received']);return DataRow(cells:[DataCell(Text('${r['date']}')),DataCell(Text('${r['item']}')),DataCell(Text('$q')),DataCell(Text('$rec')),DataCell(Text('${r['days']}')),DataCell(Text('₹${rs(r['amount'])}')),DataCell(Text('${q-rec}'))]);}).toList()))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));}
Future<void>invoiceForm(BuildContext c,Store s)async{if(s.rentals.isEmpty){showDialog(context:c,builder:(_)=>const AlertDialog(title:Text('Invoice'),content:Text('Create a rental first.')));return;}final r=s.rentals.last;final d=pw.Document();d.addPage(pw.Page(build:(_)=>pw.Padding(padding:const pw.EdgeInsets.all(30),child:pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text('RentFlow',style:pw.TextStyle(fontSize:28,fontWeight:pw.FontWeight.bold)),pw.Text('By PaliaAPK HUB'),pw.SizedBox(height:24),pw.Text('INVOICE',style:pw.TextStyle(fontSize:22,fontWeight:pw.FontWeight.bold)),pw.SizedBox(height:12),pw.Text('Customer: ${r['customer']}'),pw.Text('Item: ${r['item']}'),pw.Text('Date: ${r['date']}'),pw.Text('Qty: ${r['qty']}  Days: ${r['days']}'),pw.Text('Rate: ₹${rs(r['rate'])}'),pw.SizedBox(height:16),pw.Text('TOTAL: ₹${rs(r['amount'])}',style:pw.TextStyle(fontSize:18,fontWeight:pw.FontWeight.bold))]))));await Printing.sharePdf(bytes:await d.save(),filename:'RentFlow-Invoice.pdf');}
